function resolveValidator(tool: StoredTool): ValidateFunction {
  if (typeof tool.definitionSource !== 'function') return tool.validateInput;
  const resolved = tool.definitionSource();
  return getOrCompileSchema(resolved.name, resolved.inputSchema);
}

const compiledSchemas = new WeakMap<Record<string, unknown>, ValidateFunction>();

function getOrCompileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  const cached = compiledSchemas.get(schema);
  if (cached) return cached;
  const compiled = compileSchema(toolName, schema);
  compiledSchemas.set(schema, compiled);
  return compiled;
}

const ajv = new Ajv({allErrors: true});

function rejectInvalidInput(
  name: string,
  input: Record<string, unknown>,
  errors: ValidateFunction['errors']
): ToolResponse {
  const reason = ajv.errorsText(errors);
  log.warn('tool', 'tool input rejected', {name, inputKeys: Object.keys(input), reason});
  return {result: `Invalid tool input for "${name}": ${reason}`};
}

function compileSchema(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${(error as Error).message}`, {cause: error});
  }
}

